// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount, uint256 amount2) public {
        vm.assume(actor != address(0));
        vm.assume(amount <= address(this).balance / 2);
        vm.assume(amount2 <= address(this).balance / 2);
        vm.deal(actor, amount + amount2);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        bool ok;
        vm.prank(actor);
        try c.addToBalance{value: amount2}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
